//! Integration tests derived from examples.
//!
//! Each test creates manifolds the same way the project examples do,
//! then compares the result against a known-good bincode fixture using
//! `Manifold::approx_eq` for epsilon-based comparison.
//!
//! Fixtures are generated by: `cargo run --bin generate_fixtures`

// ExtrudePoly trait is needed for extrude() and revolve() methods on geo types
use boolmesh::prelude::ExtrudePoly;
use boolmesh::prelude::compose;
use boolmesh::prelude::Manifold;
use geo::Rect;
use geo::Coord;

mod helpers {
    use boolmesh::prelude::*;
    use geo::{BooleanOps, Coord, LineString, MultiPolygon, Polygon, Rect};
    use nalgebra::Vector3;

    pub fn cube() -> Manifold<f64> {
        generate_cube::<f64>().unwrap()
    }

    pub fn cylinder() -> Manifold<f64> {
        generate_cylinder::<f64>(1., 1., 30, 10).unwrap()
    }

    pub fn uv_sphere() -> Manifold<f64> {
        generate_uv_sphere::<f64>(30, 30).unwrap()
    }

    pub fn icosphere() -> Manifold<f64> {
        generate_icosphere::<f64>(1).unwrap()
    }

    pub fn torus() -> Manifold<f64> {
        generate_torus::<f64>(1., 0.1, 30, 30).unwrap()
    }

    pub fn cone() -> Manifold<f64> {
        generate_cone::<f64>(
            Vector3::new(0., 0., 0.),
            Vector3::new(0., 0., 1.),
            1.,
            30,
        )
        .unwrap()
    }

    pub fn hollow_square() -> MultiPolygon<f64> {
        let square = Rect::new(Coord { x: -0.5, y: -0.5 }, Coord { x: 0.5, y: 0.5 }).to_polygon();
        let hole = Rect::new(Coord { x: -0.25, y: -0.25 }, Coord { x: 0.25, y: 0.25 }).to_polygon();
        let result = square.boolean_op(&hole, geo::OpType::Difference);
        canonicalize_polygon(&result)
    }

    pub fn square_with_bite() -> MultiPolygon<f64> {
        let square = Rect::new(Coord { x: 0.0, y: -0.5 }, Coord { x: 1.0, y: 0.5 }).to_polygon();
        let bite = Rect::new(Coord { x: 0.25, y: -0.25 }, Coord { x: 0.75, y: 0.5 }).to_polygon();
        let result = square.boolean_op(&bite, geo::OpType::Difference);
        canonicalize_polygon(&result)
    }

    /// Canonicalize a MultiPolygon by removing duplicate closing points and starting
    /// each ring at the lexicographically smallest coordinate. This ensures consistent
    /// triangulation regardless of geo crate internal ordering.
    fn canonicalize_polygon(poly: &MultiPolygon<f64>) -> MultiPolygon<f64> {
        use geo::LineString;
        let polygons: Vec<_> = poly.0.iter().map(|p| {
            let ext = canonicalize_ring(p.exterior());
            let ints: Vec<_> = p.interiors().iter().map(|r| canonicalize_ring(r)).collect();
            Polygon::new(ext, ints)
        }).collect();
        MultiPolygon(polygons)
    }

    fn canonicalize_ring(ring: &LineString<f64>) -> LineString<f64> {
        let coords: Vec<_> = ring.coords().map(|c| Coord { x: c.x, y: c.y }).collect();
        // Remove duplicate closing point (first == last)
        let mut unique = coords;
        if unique.len() >= 2 && unique[0].x == unique[unique.len()-1].x && unique[0].y == unique[unique.len()-1].y {
            unique.pop();
        }
        // Rotate so the lexicographically smallest coord comes first
        if unique.len() >= 2 {
            let min_idx = (1..unique.len()).min_by(|&i, &j| {
                (unique[i].x, unique[i].y).partial_cmp(&(unique[j].x, unique[j].y)).unwrap_or(std::cmp::Ordering::Equal)
            }).unwrap_or(1);
            if min_idx > 0 {
                unique.rotate_left(min_idx);
            }
        }
        // Add closing point
        unique.push(unique[0]);
        LineString::from(unique)
    }

    /// Compare two MultiPolygon results with epsilon tolerance for coords.
    /// Polygons are sorted by centroid before comparison to handle ordering differences.
    pub fn polygons_approx_eq(a: &MultiPolygon<f64>, b: &MultiPolygon<f64>, eps: f64) -> bool {
        if a.0.len() != b.0.len() {
            return false;
        }

        // Sort polygon indices by centroid.
        let mut a_order: Vec<usize> = (0..a.0.len()).collect();
        a_order.sort_by(|&i, &j| {
            let ci = polygon_centroid(&a.0[i]);
            let cj = polygon_centroid(&a.0[j]);
            ci.0.partial_cmp(&cj.0)
                .unwrap_or(std::cmp::Ordering::Equal)
                .then_with(|| ci.1.partial_cmp(&cj.1).unwrap_or(std::cmp::Ordering::Equal))
        });

        let mut b_order: Vec<usize> = (0..b.0.len()).collect();
        b_order.sort_by(|&i, &j| {
            let ci = polygon_centroid(&b.0[i]);
            let cj = polygon_centroid(&b.0[j]);
            ci.0.partial_cmp(&cj.0)
                .unwrap_or(std::cmp::Ordering::Equal)
                .then_with(|| ci.1.partial_cmp(&cj.1).unwrap_or(std::cmp::Ordering::Equal))
        });

        for (&ai, &bi) in a_order.iter().zip(b_order.iter()) {
            if !polygon_approx_eq(&a.0[ai], &b.0[bi], eps) {
                return false;
            }
        }
        true
    }

    fn polygon_centroid(poly: &geo::Polygon<f64>) -> (f64, f64) {
        let coords: Vec<_> = poly.exterior().coords().collect();
        let n = coords.len() as f64;
        let cx = coords.iter().map(|c| c.x).sum::<f64>() / n;
        let cy = coords.iter().map(|c| c.y).sum::<f64>() / n;
        (cx, cy)
    }

    fn polygon_approx_eq(a: &geo::Polygon<f64>, b: &geo::Polygon<f64>, eps: f64) -> bool {
        if a.exterior().coords().count() != b.exterior().coords().count() {
            return false;
        }
        for (ca, cb) in a.exterior().coords().zip(b.exterior().coords()) {
            if (ca.x - cb.x).abs() > eps || (ca.y - cb.y).abs() > eps {
                return false;
            }
        }
        if a.interiors().len() != b.interiors().len() {
            return false;
        }
        for (ia, ib) in a.interiors().iter().zip(b.interiors().iter()) {
            if ia.coords().count() != ib.coords().count() {
                return false;
            }
            for (a_coord, b_coord) in ia.coords().zip(ib.coords()) {
                if (a_coord.x - b_coord.x).abs() > eps || (a_coord.y - b_coord.y).abs() > eps {
                    return false;
                }
            }
        }
        true
    }
}

