#[test]
fn test_primitive_cube() {
    let bytes = include_bytes!("fixtures/cube.bincode");
    let expected: Manifold<f64> = bincode::deserialize(bytes).unwrap();
    let actual = helpers::cube();
    assert!(actual.approx_eq(&expected, 1e-10), "cube geometry mismatch");
}

